public sealed class TransferFundsService(AccountRepository accounts, TransferRepository transfers)
{
    public TransferFundsResponse Execute(TransferFundsRequest request)
    {
        // TextBox.Text is never null in the legacy; Trim() is applied to both accounts.
        string origen = (request.Origen ?? string.Empty).Trim();
        string destino = (request.Destino ?? string.Empty).Trim();
        // decimal.Parse on a missing value throws in the legacy.
        decimal monto = request.Monto ?? throw new ArgumentNullException(nameof(request.Monto));
        string? tipo = request.Tipo;

        // RULE-005: before any data access.
        if (origen == destino)
        {
            throw new BusinessError("SAME_ACCOUNT", "-1", "LA CUENTA DESTINO ES LA MISMA");
        }

        // RULE-006
        var cuenta = accounts.FindByNumber(origen);
        if (cuenta is null)
        {
            throw new BusinessError("ORIGIN_ACCOUNT_NOT_FOUND", "-1", "CUENTA ORIGEN NO EXISTE");
        }
        string? estado = cuenta.CtaEstado;
        decimal saldo = cuenta.CtaSaldo!.Value;
        if (estado != "A")
        {
            throw new BusinessError("ORIGIN_ACCOUNT_INACTIVE", "-1", "CUENTA ORIGEN INACTIVA");
        }

        // RULE-007
        if (!accounts.ExistsActive(destino))
        {
            throw new BusinessError("DESTINATION_ACCOUNT_NOT_FOUND", "-1", "CUENTA DESTINO NO EXISTE");
        }

        // RULE-008
        decimal comision = Calcular(monto, tipo);
        if (saldo < monto + comision)
        {
            throw new BusinessError("INSUFFICIENT_BALANCE", "-1", "SALDO INSUFICIENTE");
        }

        // RULE-009 (affected row counts are ignored, as in the legacy)
        accounts.Debit(origen, monto + comision);
        accounts.Credit(destino, monto);

        // RULE-010
        int numero = transfers.NextNumber();
        transfers.Register(numero, origen, destino, monto, comision, tipo);

        return new TransferFundsResponse(numero, comision, "TRANSFERENCIA REALIZADA");
    }

    // ComisionService.Calcular
    private static decimal Calcular(decimal monto, string? tipo)
    {
        decimal comision = monto <= 1000m
            ? 0.50m
            : Math.Round(monto * 0.001m, 2, MidpointRounding.AwayFromZero);
        if (comision > 5.00m)
        {
            comision = 5.00m;
        }
        if (tipo == "INM")
        {
            comision += 1.00m;
        }
        return comision;
    }
}
